<script setup lang="ts">
import { computed,ref } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import { api,statusMeta,type Task } from '../../api'
const items=ref<Task[]>([]),tab=ref('all'),loading=ref(false)
const visible=computed(()=>tab.value==='all'?items.value:items.value.filter(i=>i.status===tab.value))
onShow(load)
async function load(){loading.value=true;try{items.value=await api.tasks()}catch(e){uni.showToast({title:e instanceof Error?e.message:'加载失败',icon:'none'})}finally{loading.value=false}}
function open(id:number){uni.navigateTo({url:`/pages/tasks/detail?id=${id}`})}
</script>
<template><view class="page pad"><view class="between"><view><text class="page-title">执法任务</text><text class="tiny">今日任务与待办检查</text></view><text class="tag orange">{{items.filter(i=>i.status!=='completed').length}} 项待办</text></view><view class="tabs"><button v-for="t in [['all','全部'],['pending','待检查'],['in_progress','进行中'],['completed','已完成']]" :key="t[0]" :class="{on:tab===t[0]}" @click="tab=t[0]">{{t[1]}}</button></view><view v-if="loading" class="loading">正在加载任务…</view><view v-else-if="!visible.length" class="empty"><text class="empty-icon">📋</text><text>当前没有任务</text></view><view v-else class="task-list"><view class="task" v-for="item in visible" :key="item.id" @click="open(item.id)"><view class="between"><view><text class="strong">{{item.subjectName}}</text><text class="tiny">{{item.taskNo}} · {{item.taskType}}</text></view><text class="tag" :class="statusMeta(item.status).tone">{{statusMeta(item.status).label}}</text></view><text class="muted">📍 {{item.address}} · {{item.distanceKm}}km</text><view class="progress"><view :style="{width:`${item.checklistTotal?item.checklistDone/item.checklistTotal*100:0}%`}"/></view><view class="between"><text class="tiny">检查项 {{item.checklistDone}}/{{item.checklistTotal}} · {{item.deadline}}</text><text class="link">{{item.status==='pending'?'开始检查':'查看详情'}} ›</text></view></view></view></view></template>
<style lang="scss" scoped>.page-title{display:block;font-size:38rpx;font-weight:750}.tabs{display:flex;gap:8rpx;margin:18rpx 0}.tabs button{padding:11rpx 20rpx;border-radius:24rpx;background:#e9f0ec;color:#718277;font-size:20rpx}.tabs button.on{background:#12764a;color:#fff}.task{margin-bottom:14rpx;padding:20rpx;border:1rpx solid #e1e9e3;border-radius:20rpx;background:#fff}.task>view:nth-of-type(1)>view{display:flex;flex-direction:column;gap:4rpx}.task>.muted{display:block;margin:9rpx 0}.task .progress{margin:12rpx 0 8rpx}.link{color:#12764a;font-size:19rpx}</style>
